    "published": true
  },
  "x-instance-label": {
    "schema": {
      "$ref": "#/$defs/instance-label"
    },
    "title": "インスタンスの名前の型",
    "description": "インスタンスを名前で見せるときの型である。",
    "prompt": {
      "read": {
        "shown": "他から指された所と、変更を見せる画面に出る。",
        "interpret": "{…} の部分に、その欄の値が入る。"
      },
      "write": [
        {
          "id": "label-fields-exist",
          "rule": "{…} の中には、根の properties にある欄の名前だけを書く。",
          "why": "無い欄を書くと、名前を作れない。",
          "test": "{…} の中の名前が、根の properties にあるかを見る。",
